head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_row = '';
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;
scwin.gMarket = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        if (js_dep_cd.substr(0, 1) === '5') {
            // 시장감시부로 변경 20240510
            panel_BZ.hide();
            panel_mkt.hide();
        }
        rdo_MKT_ID.setValue(js_market);
        if (js_market === '1' || js_market === '2' || js_market === '6') {
            panel_mkt.hide();
        }
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        await scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30340.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    // 업무구분초기화
    const sbmOptions = {
        id : "sbm_dts_business",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_business=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 진행사항 초기화
    const sbmOptions2 = {
        id : "sbm_dts_progress_state",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_progress_state=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_EDate.setValue(vCurDate); // 현재날짜

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_SDate_onclick
 * @description img_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.img_SDate_onclick" });
    }
};

/**
 * @method
 * @name img_EDate_onclick
 * @description img_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.img_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30340.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_qnaList_OnFail
 * @description qna List On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_qnaList_OnFail = async function() {
    try {
        await $c.win.alert(dts_qnaList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30340.dts_qnaList_OnFail" });
    }
};

/**
 * @method
 * @name dts_qnaList_OnLoadError
 * @description dts_qnaList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_qnaList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_qnaList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30340.dts_qnaList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_business_OnLoadCompleted
 * @description dts_business 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_business_OnLoadCompleted = function(rowcount) {
    try {
        dts_business.setBroadcast(false);
        for (let i = 1; i <= dts_business.getRowCount(); i++) {
            if (scwin.gMarket === '1' || scwin.gMarket === '2') {
                if (dts_business.getCellData(i, 1) === '3') {
                    // '3' =지분
                    dts_business.removeRow(i);
                    i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

                }
            }
        }
        dts_business.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.dts_business_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_qnaList_OnLoadCompleted
 * @description dts_qnaList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_qnaList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_qnaList.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.dts_qnaList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        scwin.setKey(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_qnaList.getCellData(row, "ISUR_CD");
        if (colid === 'QUES_TITLE') {
            await scwin.readDetail(row, colid);
        } else if (colid === "COM_NM") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30340.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30340.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&LD_MKT_TP_CD=" + rdo_MKT_ID.getValue();
    if (js_dep_cd.substr(0, 1) === '5') {
        // 시장감시부로 변경  2024.05.10
        url += "&QUES_BZ_TP_CD=3"; // 지분만 보이기

    } else {
        url += "&QUES_BZ_TP_CD=" + cmb_business.getValue();
    }
    url += "&REPLY_YN=" + cmb_REPLY_YN.getValue();
    url += "&CONTN_TITLE=" + txb_CONTN_TITLE.getValue();
    url += "&SDATE=" + edt_SDate.getValue();
    url += "&EDATE=" + edt_EDate.getValue();
    url += "&SCREN_ID=" + "ULDSTF30340.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_qnaList",
        action : "/VocQnA.do",
        ref : "",
        target : "dts_qnaList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setKey
 * @description set Key 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setKey = function(row) {
    scwin.key_row = row;
};

/**
 * @method
 * @name readDetail
 * @description read Detail 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDetail = async function(row, colid) {
    if (colid === "QUES_TITLE") {
        if (dts_qnaList.getCellData(row, "ANS_OBJ_CONTN_ID") === '0') {
            const options = {
                id: "ULDSTF30341",
                title: "고객의소리 Q&A 질문",
                type: "browserPopup",
                width: "600px",
                height: 700 + 30,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/bizspt/ULDSTF30341.gfm", options);
        } else {
            const options = {
                id: "ULDSTF30342",
                title: "고객의소리 Q&A 답변",
                type: "browserPopup",
                width: "600px",
                height: 460 + 30,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/bizspt/ULDSTF30342.gfm", options);
        }
    }
};

/**
 * @method
 * @name setId
 * @description set Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(obj) {
    if (scwin.clickId !== "input") {
        scwin.clickId = dts_qnaList.getCellData(Number(obj), "QUES_ID");
    }
};

/**
 * @method
 * @name getId
 * @description get Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getId = function() {
    return scwin.clickId;
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
